CREATE TABLE "vendor_bank_accounts" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"vendor_id" uuid NOT NULL,
	"bank_name" text NOT NULL,
	"branch_name" text NOT NULL,
	"account_name" text NOT NULL,
	"account_number" text NOT NULL,
	"routing_or_swift_code" text,
	"is_primary" boolean DEFAULT false NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "vendor_bank_accounts_bank_name_check" CHECK (btrim("vendor_bank_accounts"."bank_name") <> ''),
	CONSTRAINT "vendor_bank_accounts_branch_name_check" CHECK (btrim("vendor_bank_accounts"."branch_name") <> ''),
	CONSTRAINT "vendor_bank_accounts_account_name_check" CHECK (btrim("vendor_bank_accounts"."account_name") <> ''),
	CONSTRAINT "vendor_bank_accounts_account_number_check" CHECK ("vendor_bank_accounts"."account_number" ~ '^[A-Za-z0-9]{4,34}$'),
	CONSTRAINT "vendor_bank_accounts_routing_or_swift_code_check" CHECK ("vendor_bank_accounts"."routing_or_swift_code" IS NULL OR "vendor_bank_accounts"."routing_or_swift_code" ~ '^[A-Za-z0-9]{4,20}$')
);
