-- Hand-added. A vendor inserted without a list (the column default is empty) serves its own
-- Palika, so the CHECKs hold for every insert that does not name the column.
CREATE FUNCTION default_vendor_serviceable_palikas() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF cardinality(NEW.serviceable_palikas) = 0 THEN
    NEW.serviceable_palikas := ARRAY[NEW.municipality_palika_string];
  END IF;
  RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER vendors_default_serviceable_palikas BEFORE INSERT ON vendors
  FOR EACH ROW EXECUTE FUNCTION default_vendor_serviceable_palikas();
--> statement-breakpoint
